const env = $json ?? {};

const tgText =
  env.telegram?.message?.text ??
  env.telegram?.callback_query?.message?.text ??
  env.telegram?.callback_query?.data ??
  "";

const questionRaw =
  env.input?.question ??
  env.question ??
  env.input?.text ??
  tgText;

const answerRaw =
  env.output?.reply_text ??
  env.answer ??
  env.output?.answer ??
  "";

const trace_id = (env.trace_id ?? env.meta?.request_id ?? "").toString();
const user_id = (env.user_id ?? env.input?.user_id ?? env.telegram?.message?.from?.id ?? env.telegram?.callback_query?.from?.id ?? "").toString();

// КЛЮЧЕВОЕ: никогда не null
const question = (questionRaw == null ? "[missing]" : String(questionRaw));
const answer = (answerRaw == null ? "" : String(answerRaw));

return [{
  json: {
    trace_id,
    user_id,
    question,
    answer,
    top_score: env.retrieval?.top_score ?? env.top_score ?? null,
    fallback_type: env.decision?.mode ?? env.fallback_type ?? null,
    prompt_version: env.meta?.prompt_version ?? null,
    model: env.meta?.model ?? null,
    latency_ms: env.latency_ms ?? env.timers?.latency_ms ?? null,
    sources_json: env.retrieval ? { retrieval: env.retrieval } : (env.sources_json ?? {}),
  }
}];
